function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is an integer between 1 and 100000.';
  return null;
}

