function canConstruct(s, k) {
  if (s.length < k) {
    return false;
  }
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  let oddLetters = 0;
  for (const count of counts) {
    if (count % 2 === 1) {
      oddLetters++;
    }
  }
  return oddLetters <= k;
}

