function canConstruct(s, k) {
  // Try every way to put the positions of s into exactly k non-empty groups
  // (group[i] is the group of position i; groups are numbered in order of first use).
  const n = s.length;
  if (k > n) return false;
  const group = new Array(n).fill(-1);
  const usedBefore = new Array(n + 1).fill(0);
  const allPalindromes = () => {
    for (let g = 0; g < k; g++) {
      const freq = new Map();
      for (let j = 0; j < n; j++) if (group[j] === g) freq.set(s[j], (freq.get(s[j]) || 0) + 1);
      if ([...freq.values()].filter(c => c % 2 === 1).length > 1) return false;
    }
    return true;
  };
  let i = 0;
  while (i >= 0) {
    if (i === n) {
      if (usedBefore[n] === k && allPalindromes()) return true;
      i--;
      continue;
    }
    group[i]++;
    if (group[i] > Math.min(usedBefore[i], k - 1)) { group[i] = -1; i--; continue; }
    usedBefore[i + 1] = Math.max(usedBefore[i], group[i] + 1);
    if (k - usedBefore[i + 1] > n - i - 1) continue;
    i++;
  }
  return false;
}

