function generate(rand, size) {
  const large = size === 'large';
  const alphabet = 1 + Math.floor(rand() * (large ? 26 : 4));
  const n = large ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 7);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  let k;
  const pick = rand();
  if (large) {
    if (pick < 0.15) k = n + 1 + Math.floor(rand() * (100000 - n));
    else if (pick < 0.3) k = n - Math.floor(rand() * 3);
    else k = 1 + Math.floor(rand() * 30);
  } else {
    k = 1 + Math.floor(rand() * (n + 2));
  }
  return [s, k];
}
